import { installAtmosphereDebug } from '@client/atmosphere-debug';
import { WeaponHud } from '@client/ui/weapon-hud';
import { playCombatFx, type CombatEvent } from '@client/fx';
import { recordCombatEvent } from '@client/fx-debug';
import type { WeaponId } from '@shared/weapons';

const [inShip, setInShip] = React.useState(false);
// TASK-43: the weapon HUD state — the active weapon (1/2 keys, client
// state), the SELF ship's classId + energy (10 Hz entity_update), and the
// two transient server denial prompts (error frames {code}).
const [weapon, setWeapon] = React.useState<WeaponId>('laser');
const [selfShip, setSelfShip] = React.useState<{ classId: string; energy: number | null } | null>(
  null,
);
const [lowEnergy, setLowEnergy] = React.useState(false);
const [locked, setLocked] = React.useState(false);
// Refs (the fire handlers are captured once — no stale closures):
const weaponRef = React.useRef<WeaponId>('laser');
const selfShipRef = React.useRef(false);
const selfPosRef = React.useRef<{ x: number; y: number; z: number } | null>(null);
const remoteShipsRef = React.useRef<{ id: string; pos: { x: number; y: number; z: number } }[]>(
  [],
);
const promptTimers = React.useRef<{ low: number; locked: number }>({ low: 0, locked: 0 });

if (msg.type === 'combat_event') {
  // TASK-43: the ONE FX entry point — server events only (a denied
  // fire never produced an event, so it never produces FX).
  const ev = msg.payload as CombatEvent;
  recordCombatEvent(ev);
  const world = worldRef.current;
  if (world) {
    playCombatFx(
      world.fx,
      ev,
      (id) => {
        if (id === selfShipIdRef.current) return selfPosRef.current;
        return remoteShipsRef.current.find((t) => t.id === id)?.pos ?? null;
      },
    );
  }
  return;
}
if (msg.type === 'error') {
  // TASK-43: the weapon denial prompts (transient, self-clearing).
  const code = (msg.payload as { code: string }).code;
  if (code === 'low-energy') {
    setLowEnergy(true);
    window.clearTimeout(promptTimers.current.low);
    promptTimers.current.low = window.setTimeout(() => setLowEnergy(false), 1500);
  } else if (code === 'weapon-locked') {
    setLocked(true);
    window.clearTimeout(promptTimers.current.locked);
    promptTimers.current.locked = window.setTimeout(() => setLocked(false), 3000);
  }
  return;
}
if (msg.type !== 'presence') return;

text:
Wait a sec — "selfShipIdRef" is used inside onMessage, but it's declared after useGameSession (around line 482, after "const clientRef"). The onMessage callback is defined inside the hook's effect and is only executed after mount — the TDZ (Temporal Dead Zone) only becomes a problem when the closure references a const before its initialization during the execution of the render. The closure references "selfShipIdRef" which is declared later in the function body — at the point when the effect executes (after render completes), the ref already exists. Closures capture the binding, and by the time it's called it's already initialized. This is the same pattern as "worldRef" which is declared later (per the comment on line 538, it's an accepted pattern). No problem.

Next is the onSelfEntity callback: add a set for selfShip. Inside the hook's onSelfEntity, in the else branch there's "setInShip(self?.kind === 'ship')". Extend this:

```tsx
setInShip(self?.kind === 'ship');
if (self && self.kind === 'ship') {
  selfShipRef.current = true;
  selfPosRef.current = { ...self.pos };
  setSelfShip({ classId: self.classId, energy: self.energy ?? null });
  world.reEnterShip(...)
} else {
  selfShipRef.current = false;
  ...
}
```
And in the on-foot branch (character): setSelfShip(null); selfShipRef.current = false.

Also on onSnapshotEntities (system switch): clear selfShip. The onSelfEntity call also happens at snapshot time — good (onSnapshot calls onSelfEntity). But in the case where a snapshot has no self entity... onSelfEntity(null, null) → the else branch clears it. OK.

Regarding onWorldEntities (the remoteShipsRef update) — the onWorldEntities callback in App:
```tsx
(entities) => {
  interactTargetsRef.current = interactableTargetsFrom(entities);
  feedRemote(entities);
},
```
Add: "remoteShipsRef.current = entities.filter((e) => (e.kind === 'ship' || e.kind === 'ai-ship') && e.callsign !== sessionCallsignRef.current).map((e) => ({ id: e.id, pos: { ...e.pos } }));"

Note: one's own ship has one's own callsign → excluded. One's own character is kind 'character' → excluded. Good.

